  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <div class="shell" id="app"></div>

  <script>
    const featuredProducts = [
      {
        name: "Meridian Knit Sweater",
        price: "$88",
        badge: "Bestseller",
        detail: "Soft merino blend with a boxy drape and tonal ribbing.",
