      return `
        <header class="topbar">
          <a class="brand" href="#maincontent" aria-label="Northstar Retail home">
            <span class="brand-mark" aria-hidden="true">N</span>
            Northstar Retail
          </a>
          <div class="top-actions">
            <span class="pill">Dark edit</span>
            <a class="pill" href="#featured">Featured</a>
            <a class="pill" href="#deals">Deals</a>
            <a class="pill" href="#journal">Journal</a>
            <button class="button secondary" type="button" aria-label="Bag items: 0">
              Bag <span id="bag-count" aria-hidden="true">0</span>
            </button>
          </div>
        </header>

        <main id="maincontent" tabindex="-1">
          <section class="hero" aria-labelledby="hero-title">
