    }
    h2 {
      font-size: clamp(1.4rem, 2vw, 2rem);
      line-height: 1.08;
      margin-bottom: 0.3rem;
    }
    h3 {
      font-size: 1.1rem;
      line-height: 1.2;
      margin-bottom: 0.45rem;
    }

    .lede {
      max-width: 60ch;
      color: var(--color-muted-text);
      font-size: 1.05rem;
    }

    .hero-actions {
      display: flex;
      gap: 0.8rem;
      flex-wrap: wrap;
      margin: 1.2rem 0 1.3rem;
    }

    .signal-row {
      display: flex;
      gap: 1rem;
      flex-wrap: wrap;
      padding-top: 1rem;
      border-top: 1px solid var(--color-border);
    }

    .signal {
      min-width: 120px;
    }
    .signal strong {
      display: block;
      font-size: 1.25rem;
      margin-bottom: 0.2rem;
    }
    .signal span { color: var(--color-muted-text); font-size: 0.94rem; }

    .hero-visual {
