      padding: 1.05rem;
      border-radius: 24px;
      border: 1px solid rgba(143, 211, 255, 0.14);
      background:
        linear-gradient(160deg, rgba(16, 22, 33, 0.98), rgba(20, 32, 45, 0.98)),
        radial-gradient(circle at top right, rgba(143, 211, 255, 0.18), transparent 36%);
    }

    .promo strong { font-size: 1.2rem; }

    .story-card {
      display: grid;
      grid-template-rows: auto 1fr;
      background: linear-gradient(180deg, rgba(23, 29, 42, 0.98), rgba(15, 18, 27, 0.98));
    }

    .story-card img {
      aspect-ratio: 16 / 9;
      object-fit: cover;
      width: 100%;
    }

    .story-body {
      display: grid;
      gap: 0.75rem;
      padding: 1rem;
    }

    .story-body .meta-row {
      font-size: 0.88rem;
    }

    .live-region {
      position: sticky;
      bottom: 1rem;
      width: min(100%, 540px);
      margin: 1rem auto 0;
      padding: 0.95rem 1rem;
      border-radius: 18px;
      border: 1px solid var(--color-border);
      background: rgba(18, 23, 34, 0.94);
      box-shadow: var(--shadow);
      color: var(--color-muted-text);
    }

    footer {
      margin-top: 1.2rem;
      padding: 1rem 0 0.5rem;
      color: var(--color-muted-text);
    }

    .footer-bar {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      flex-wrap: wrap;
      padding: 1rem 0 0;
      border-top: 1px solid var(--color-border);
    }

    .footer-links {
      display: flex;
      gap: 1rem;
      flex-wrap: wrap;
      padding: 0;
      margin: 0;
      list-style: none;
    }

    @media (max-width: 960px) {
      .hero, .grid.products, .grid.deals, .grid.editorial { grid-template-columns: 1fr 1fr; }
      .hero { grid-template-columns: 1fr; }
    }

    @media (max-width: 680px) {
      .shell { width: min(100% - 1rem, 1180px); }
      .topbar, .section-head, .footer-bar { align-items: start; }
      .topbar, .hero-copy, .hero-visual, .panel { border-radius: 22px; }
      .grid.products, .grid.deals, .grid.editorial { grid-template-columns: 1fr; }
      .section-head { flex-direction: column; }
      h1 { max-width: none; }
    }

    @media (prefers-reduced-motion: no-preference) {
      html { scroll-behavior: smooth; }
    }

    @media (forced-colors: active) {
