<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <meta name="color-scheme" content="dark light" />
  <title>Northstar Retail — Modern essentials for the season</title>
  <style>
    :root {
      --color-bg: #0b0d12;
      --color-surface: #121722;
      --color-surface-elevated: #171d2a;
      --color-border: #2a3243;
      --color-text: #f3f5f8;
      --color-muted-text: #a8b1c2;
      --color-link: #8fd3ff;
      --color-accent: #69f0c5;
      --color-accent-strong: #2ad4a4;
      --color-warm: #ffbb78;
      --color-focus: #8fd3ff;
      --shadow: 0 18px 40px rgba(0, 0, 0, 0.32);
      color-scheme: dark;
    }

    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body {
      margin: 0;
      min-width: 320px;
      background:
        radial-gradient(circle at top left, #182033 0, transparent 34%),
        radial-gradient(circle at top right, #15283a 0, transparent 32%),
        var(--color-bg);
      color: var(--color-text);
      font: 16px/1.5 Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    img { max-width: 100%; display: block; }
    a { color: var(--color-link); text-decoration-thickness: 0.08em; text-underline-offset: 0.18em; }
    a:hover { color: #b0e3ff; }
    a:focus-visible, button:focus-visible {
      outline: 3px solid var(--color-focus);
      outline-offset: 3px;
      border-radius: 14px;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      z-index: 999;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--color-surface-elevated);
      color: var(--color-text);
      transform: translateY(-180%);
      transition: transform 160ms ease;
    }
    .skip-link:focus, .skip-link:active { transform: translateY(0); }

    .shell {
      width: min(1180px, calc(100% - 2rem));
      margin: 0 auto;
      padding: 1rem 0 3rem;
    }

    .topbar, .panel, .card, .story-card {
      border: 1px solid var(--color-border);
      background: rgba(18, 23, 34, 0.96);
      box-shadow: var(--shadow);
    }

    .topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1rem 1.15rem;
      border-radius: 24px;
      backdrop-filter: blur(14px);
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.8rem;
      color: var(--color-text);
      text-decoration: none;
      font-weight: 700;
      letter-spacing: 0.03em;
      white-space: nowrap;
    }

    .brand-mark {
      width: 2.5rem;
      height: 2.5rem;
      border-radius: 0.9rem;
      display: grid;
      place-items: center;
      color: #081015;
