    .signal {
      min-width: 120px;
    }
    .signal strong {
      display: block;
      font-size: 1.25rem;
      margin-bottom: 0.2rem;
    }
    .signal span { color: var(--color-muted-text); font-size: 0.94rem; }

    .hero-visual {
      display: grid;
      gap: 1rem;
      align-content: start;
      background:
        radial-gradient(circle at top right, rgba(105, 240, 197, 0.18), transparent 34%),
        radial-gradient(circle at bottom left, rgba(143, 211, 255, 0.18), transparent 36%),
