    }

    .product-link {
      color: var(--color-text);
      text-decoration: none;
    }
    .product-link:hover { color: #dff7ff; }

    .card p, .story-card p { color: var(--color-muted-text); }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.65rem;
      align-items: center;
      margin-top: auto;
    }

    .promo {
      display: grid;
      gap: 0.8rem;
      min-height: 100%;
      padding: 1.05rem;
      border-radius: 24px;
      border: 1px solid rgba(143, 211, 255, 0.14);
      background:
