        alt: "Contour Weekender Bag in charcoal with warm accent panels.",
        hue: "#37404d",
        accent: "#ffbb78"
      },
      {
        name: "Studio Layer Coat",
        price: "$190",
        badge: "Staff pick",
        detail: "Tailored outerwear built for cold commutes and polished layering.",
        alt: "Studio Layer Coat in midnight navy with a clean silhouette.",
        hue: "#232c45",
