        action: "See shipping",
        value: "Threshold offer"
      },
      {
        title: "2-day gift wrap service",
        copy: "Elegant packaging and quick dispatch for the gifts you need this week.",
        action: "Add gift wrap",
        value: "Seasonal perk"
      }
    ];

    const editorials = [
      {
        title: "How the design team builds a smarter capsule wardrobe",
        category: "Editorial",
        readTime: "6 min read",
        summary: "A closer look at texture, proportion, and color when every piece has to earn its place.",
        alt: "Styled flat lay with neutral garments and accessories under studio light.",
        hue: "#20283b",
        accent: "#8fd3ff"
      },
      {
        title: "Four routes to an elevated weekend bag",
        category: "Guide",
        readTime: "4 min read",
        summary: "From commuting to overnight travel, the right silhouette can carry more than you expect.",
        alt: "Travel bag and packing essentials arranged beside a folded coat.",
        hue: "#322f3d",
        accent: "#ffbb78"
      },
      {
        title: "Why muted color palettes feel richer in dark spaces",
        category: "Story",
        readTime: "5 min read",
        summary: "Our editors unpack the balance of low-light warmth, contrast, and tactile materials.",
        alt: "Warm ambient styling scene with layered textiles and a reading lamp.",
        hue: "#2d403d",
        accent: "#69f0c5"
      }
    ];

    function svgDataUri(title, hue, accent) {
      const safeTitle = title.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
      const svg = `
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 600" role="img" aria-labelledby="title desc">
          <title>${safeTitle}</title>
          <desc>${safeTitle} rendered as a stylized product illustration.</desc>
          <defs>
            <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
              <stop offset="0%" stop-color="${hue}" />
              <stop offset="100%" stop-color="#101523" />
            </linearGradient>
            <radialGradient id="glow" cx="70%" cy="25%" r="60%">
              <stop offset="0%" stop-color="${accent}" stop-opacity="0.9" />
              <stop offset="100%" stop-color="${accent}" stop-opacity="0" />
            </radialGradient>
          </defs>
          <rect width="800" height="600" fill="url(#bg)" />
          <rect width="800" height="600" fill="url(#glow)" />
          <circle cx="620" cy="110" r="90" fill="${accent}" fill-opacity="0.16" />
          <circle cx="170" cy="500" r="130" fill="#ffffff" fill-opacity="0.07" />
          <path d="M160 410c85-92 194-138 292-138 82 0 151 30 211 90" fill="none" stroke="#ffffff" stroke-opacity="0.14" stroke-width="22" stroke-linecap="round" />
          <path d="M220 390c56-50 118-76 186-76 64 0 124 20 180 62" fill="none" stroke="${accent}" stroke-opacity="0.72" stroke-width="10" stroke-linecap="round" />
          <text x="62" y="110" fill="#fff" fill-opacity="0.92" font-family="Inter,Segoe UI,sans-serif" font-size="54" font-weight="700">${safeTitle}</text>
          <text x="64" y="160" fill="#fff" fill-opacity="0.62" font-family="Inter,Segoe UI,sans-serif" font-size="24">Northstar retail studio</text>
        </svg>`;
      return "data:image/svg+xml;charset=UTF-8," + encodeURIComponent(svg);
    }

    function slugify(text) {
      return text.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
    }

    function productCard(product) {
      const slug = slugify(product.name);
      return `
        <article class="card" id="${slug}">
          <span class="tag">${product.badge}</span>
          <figure>
            <img src="${svgDataUri(product.name, product.hue, product.accent)}" alt="${product.alt}" />
          </figure>
          <div>
            <h3><a class="product-link" href="#${slug}">${product.name}</a></h3>
            <p>${product.detail}</p>
          </div>
          <div class="meta-row">
            <span class="price">${product.price}</span>
            <span>Free returns</span>
          </div>
          <div class="actions">
            <button class="button" type="button" data-add-to-bag="${product.name}" aria-label="Add to bag: ${product.name}">Add to bag</button>
            <button class="button secondary" type="button" aria-label="Save ${product.name} for later">Save</button>
          </div>
        </article>
      `;
    }

    function dealCard(deal) {
      return `
        <article class="promo">
          <span class="tag">${deal.value}</span>
          <h3>${deal.title}</h3>
          <p>${deal.copy}</p>
          <button class="button secondary" type="button">${deal.action}</button>
        </article>
      `;
    }

    function editorialCard(item) {
      const slug = slugify(item.title);
      return `
        <article class="story-card" id="story-${slug}">
          <img src="${svgDataUri(item.title, item.hue, item.accent)}" alt="${item.alt}" />
          <div class="story-body">
            <div class="meta-row">
              <span class="tag">${item.category}</span>
              <span>${item.readTime}</span>
            </div>
            <h3><a class="product-link" href="#story-${slug}">${item.title}</a></h3>
            <p>${item.summary}</p>
          </div>
        </article>
      `;
    }

    function app() {
      return `
        <header class="topbar">
          <a class="brand" href="#maincontent" aria-label="Northstar Retail home">
            <span class="brand-mark" aria-hidden="true">N</span>
            Northstar Retail
          </a>
          <div class="top-actions">
            <span class="pill">Dark edit</span>
            <a class="pill" href="#featured">Featured</a>
            <a class="pill" href="#deals">Deals</a>
            <a class="pill" href="#journal">Journal</a>
            <button id="bag-button" class="button secondary" type="button" aria-label="Bag items: 0">
              Bag <span id="bag-count" aria-hidden="true">0</span>
            </button>
          </div>
        </header>

        <main id="maincontent" tabindex="-1">
          <section class="hero" aria-labelledby="hero-title">
            <div class="hero-copy">
              <p class="eyebrow">Retail essentials, curated</p>
              <h1 id="hero-title">A dark, polished home for modern retail.</h1>
              <p class="lede">
                Discover featured products, time-sensitive deals, and editorial stories designed to help shoppers move from inspiration to checkout without friction.
              </p>
              <div class="hero-actions">
                <a class="button" href="#featured">Shop featured</a>
                <a class="button secondary" href="#journal">Read the journal</a>
              </div>
              <div class="signal-row" aria-label="Store highlights">
                <div class="signal">
                  <strong>48 hrs</strong>
                  <span>curated drops</span>
                </div>
                <div class="signal">
                  <strong>2-day</strong>
                  <span>premium delivery</span>
                </div>
                <div class="signal">
                  <strong>4.9/5</strong>
                  <span>editor-approved picks</span>
                </div>
              </div>
            </div>
            <section class="hero-visual" aria-labelledby="spotlight-title">
              <h2 id="spotlight-title" class="sr-only">Seasonal spotlight</h2>
              <div class="visual-panel">
                <img src="${svgDataUri("Seasonal spotlight", "#1d2837", "#8fd3ff")}" alt="Seasonal spotlight in a moody retail display with layered product silhouettes." />
                <div class="visual-meta">
                  <div>
                    <strong>Autumn edit</strong>
                    <span>Refined textures and subdued color</span>
                  </div>
                  <a href="#deals">View offers</a>
                </div>
              </div>
            </section>
          </section>

          <section class="panel" id="featured" aria-labelledby="featured-heading">
            <div class="section-head">
              <div>
                <p class="eyebrow">Featured products</p>
                <h2 id="featured-heading">Highly shoppable, thoughtfully presented.</h2>
              </div>
              <p>Each card keeps one primary product link and separate actions, so browsing stays predictable on keyboard and screen reader navigation.</p>
            </div>
            <div class="grid products">
              ${featuredProducts.map(productCard).join("")}
            </div>
          </section>

          <section class="panel" id="deals" aria-labelledby="deals-heading">
            <div class="section-head">
              <div>
                <p class="eyebrow">Deals</p>
                <h2 id="deals-heading">Offers that feel editorial, not noisy.</h2>
              </div>
              <p>Promotions use clear labels and a visual hierarchy that remains legible at smaller widths.</p>
            </div>
            <div class="grid deals">
              ${deals.map(dealCard).join("")}
            </div>
          </section>

          <section class="panel" id="journal" aria-labelledby="journal-heading">
            <div class="section-head">
              <div>
                <p class="eyebrow">Editorial content</p>
                <h2 id="journal-heading">Stories that help shoppers decide.</h2>
              </div>
              <p>Editorial modules use a clear article structure with meaningful imagery and concise summaries.</p>
            </div>
            <div class="grid editorial">
              ${editorials.map(editorialCard).join("")}
            </div>
          </section>
        </main>

        <div class="live-region" id="status" role="status" aria-live="polite">
          Ready for browsing.
        </div>

        <footer>
          <div class="footer-bar">
            <p>Northstar Retail © 2026</p>
            <nav aria-label="Footer">
              <ul class="footer-links">
                <li><a href="#maincontent">Top</a></li>
                <li><a href="#featured">Featured</a></li>
                <li><a href="#deals">Deals</a></li>
                <li><a href="#journal">Journal</a></li>
              </ul>
            </nav>
          </div>
        </footer>
      `;
    }

    document.getElementById("app").innerHTML = app();

    const status = document.getElementById("status");
    const bagCount = document.getElementById("bag-count");
    const bagButton = document.getElementById("bag-button");
    let count = 0;

    document.addEventListener("click", (event) => {
      const addButton = event.target.closest("[data-add-to-bag]");
      if (!addButton) return;
      count += 1;
      bagCount.textContent = String(count);
      bagButton.setAttribute("aria-label", `Bag items: ${count}`);
      status.textContent = `${addButton.dataset.addToBag} added to bag.`;
    });
  </script>
</body>
